using System;
using System.Collections;
using System.Collections.Generic;
using LittleLeo.Events;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CorruptedRepairEffect", menuName = "Data/Battle/Effects/Enemy/CorruptedRepair Effect")]
public class CorruptedRepairEffect : Effect
{
	[Header("Spawn Minion Action")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private CorruptedWeldingEffect corruptedWeldingEffect;

	[SerializeField]
	private int corruptedWeldingEffectToAddAmount;

	[SerializeField]
	private ListCorruptedAnimalDataEvent OnSpawnMinionsUsingMinionsListWithoutModifications;

	[SerializeField]
	private FloatEvent OnOverrideSpawnMinionsFinalDelay;

	[SerializeField]
	private float overrideSpawnMinionsFinalDelay;

	[SerializeField]
	private FloatEvent OnOverrideSpawnMinionDelayWithVFX;

	[SerializeField]
	private float overrideSpawnMinionDelayWithVFX;

	[SerializeField]
	private GameObjectEvent OnSpawnMinionVFX;

	[NonSerialized]
	private int timesRepairedMinionLeft;

	[NonSerialized]
	private int timesRepairedMinionRight;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return Smart.Format(GetLocalizedDescription(), base.localizationManager.GetLocalizedAtTheStartOfEnemiesTurn(), corruptedWeldingEffectToAddAmount);
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		timesRepairedMinionLeft = 0;
		timesRepairedMinionRight = 0;
	}

	public override int ActivateEffect(int amount, GameObject effectOwner)
	{
		if (currentCorruptedAnimals.activeCorruptedAnimals.Count == 3)
		{
			return amount;
		}
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		instance.ActionsQueueState.EnqueueAfterAction(CorruptedRepairCoroutine(effectOwner));
		instance.SetState(instance.ActionsQueueState);
		return amount;
	}

	private IEnumerator CorruptedRepairCoroutine(GameObject effectOwner)
	{
		bool addCorruptedWeldingToMinionLeft = false;
		bool addCorruptedWeldingToMinionRight = false;
		if (currentCorruptedAnimals.activeCorruptedAnimals.Count == 1)
		{
			timesRepairedMinionLeft += corruptedWeldingEffectToAddAmount;
			addCorruptedWeldingToMinionLeft = true;
			timesRepairedMinionRight += corruptedWeldingEffectToAddAmount;
			addCorruptedWeldingToMinionRight = true;
		}
		else if (currentCorruptedAnimals.activeCorruptedAnimals.Count == 2)
		{
			if (currentCorruptedAnimals.activeCorruptedAnimals[0] != currentCorruptedAnimals.GetCorruptionSource())
			{
				timesRepairedMinionRight += corruptedWeldingEffectToAddAmount;
				addCorruptedWeldingToMinionRight = true;
			}
			else
			{
				timesRepairedMinionLeft += corruptedWeldingEffectToAddAmount;
				addCorruptedWeldingToMinionLeft = true;
			}
		}
		effectOwner.GetComponent<UnitEffects>().IsEffectActive(this);
		yield return new WaitForSeconds(1f);
		OnOverrideSpawnMinionDelayWithVFX.Raise(overrideSpawnMinionDelayWithVFX);
		OnOverrideSpawnMinionsFinalDelay.Raise(overrideSpawnMinionsFinalDelay);
		List<CorruptedAnimalData> list = new List<CorruptedAnimalData>();
		CorruptedAnimalData corruptedAnimalData = currentCorruptedAnimals.GetCorruptionSource().GetComponent<CorruptedAnimalCorruptionStats>().CorruptedAnimalData;
		if (currentCorruptedAnimals.activeCorruptedAnimals.Count == 1)
		{
			for (int i = 0; i < corruptedAnimalData.Minions.Count; i++)
			{
				for (int j = 0; j < corruptedAnimalData.Minions[i].MinionAmount; j++)
				{
					list.Add(corruptedAnimalData.Minions[i].MinionData);
				}
			}
		}
		else
		{
			for (int k = 0; k < corruptedAnimalData.Minions.Count; k++)
			{
				for (int l = 0; l < currentCorruptedAnimals.activeCorruptedAnimals.Count; l++)
				{
					CorruptedAnimalData corruptedAnimalData2 = currentCorruptedAnimals.activeCorruptedAnimals[l].GetComponent<CorruptedAnimalInitializer>().CorruptedAnimalData;
					if (corruptedAnimalData.Minions[k].MinionData != corruptedAnimalData2 && !corruptedAnimalData2.CorruptionSource)
					{
						list.Add(corruptedAnimalData.Minions[k].MinionData);
						break;
					}
				}
			}
		}
		if (IsVFXEnabled())
		{
			OnSpawnMinionVFX.Raise(base.VfxPrefab);
		}
		OnSpawnMinionsUsingMinionsListWithoutModifications.Raise(list);
		yield return InvokeAlternatives.WaitForFrames(3);
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAfterAction(AddAugmentedWeldingCoroutine(addCorruptedWeldingToMinionLeft, addCorruptedWeldingToMinionRight));
	}

	private IEnumerator AddAugmentedWeldingCoroutine(bool addCorruptedWeldingToMinionLeft, bool addCorruptedWeldingToMinionRight)
	{
		yield return InvokeAlternatives.WaitOneFrame();
		if (addCorruptedWeldingToMinionLeft)
		{
			currentCorruptedAnimals.activeCorruptedAnimals[0].GetComponent<UnitEffects>().AddEffect(corruptedWeldingEffect, timesRepairedMinionLeft);
		}
		if (addCorruptedWeldingToMinionRight)
		{
			currentCorruptedAnimals.activeCorruptedAnimals[2].GetComponent<UnitEffects>().AddEffect(corruptedWeldingEffect, timesRepairedMinionRight);
		}
		if (addCorruptedWeldingToMinionLeft || addCorruptedWeldingToMinionRight)
		{
			yield return new WaitForSeconds(1f);
		}
	}
}
